    if isinstance(item, slice):
        # Slice access - return a new Result with subset of parsed values
        sliced_fixed = self.fixed[item]
        sliced_named = {name: value for name, value in 
                       dict(zip(range(len(self.fixed)), self.named.values()))[item].items()
                       if not isinstance(list(dict(zip(range(len(self.fixed)), self.named.keys()))[item], str)}
        # Simpler approach: reconstruct named dict maintaining order
        keys = list(self.named.keys())
        indices = range(*item.indices(len(keys)))
        sliced_named = {keys[i]: self.named[keys[i]] for i in indices}
        sliced_spans = {name: span for name, span in zip(keys, self.spans.values())[item]}
        # Better approach using index-based slicing
        all_keys = list(self.named.keys())
        sliced_indices = list(range(*item.indices(len(all_keys))))
        sliced_named = {}
        sliced_spans = {}
        for idx in sliced_indices:
            name = all_keys[idx]
            sliced_named[name] = self.named[name]
            sliced_spans[name] = self.spans[name]
        return Result(sliced_fixed, sliced_named, sliced_spans)
    elif isinstance(item, int):
        return self.fixed[item]
    return self.named[item]

